import json, sys, os
R=sys.argv[1] if len(sys.argv)>1 else '.'
out=['<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>']
for k,v in I.items():
    out.append(f'<symbol id="i-{k}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{v}</symbol>')
out.append('</defs></svg>')
open(os.path.join(R,'src','icons.svg'),'w').write(''.join(out))
emap={}
for k,v in MAP.items():
    for e in v.split(): emap[e]=k
emap['🏴‍☠️'] = 'flag'   # the pirate flag is flag + zero-width joiner + skull and crossbones
json.dump(emap, open(os.path.join(R,'src','icons.json'),'w'), ensure_ascii=False, indent=0)
print(len(I), 'icons', len(emap), 'emoji', [k for k in MAP if k not in I], [k for k in I if k not in MAP])
